// FV-Lang WASM - C ABI (wasm-bindgen 없음)
// FreeLang mini-wasm-pack 호환

use std::alloc::{alloc as sys_alloc, dealloc as sys_dealloc, Layout};

// ── 메모리 관리 ──────────────────────────────
#[no_mangle]
pub extern "C" fn alloc(size: usize) -> *mut u8 {
    let layout = Layout::from_size_align(size, 1).unwrap();
    unsafe { sys_alloc(layout) }
}

#[no_mangle]
pub extern "C" fn dealloc(ptr: *mut u8, size: usize) {
    let layout = Layout::from_size_align(size, 1).unwrap();
    unsafe { sys_dealloc(ptr, layout) }
}

// ── 결과 직렬화 헬퍼 ─────────────────────────
// 반환 형식: [4바이트 길이(LE)] + [JSON 바이트]
fn write_result(s: &str) -> *mut u8 {
    let bytes = s.as_bytes();
    let len = bytes.len();
    let total = 4 + len;
    let layout = Layout::from_size_align(total, 1).unwrap();
    unsafe {
        let ptr = sys_alloc(layout);
        let len_bytes = (len as u32).to_le_bytes();
        ptr.copy_from(len_bytes.as_ptr(), 4);
        ptr.add(4).copy_from(bytes.as_ptr(), len);
        ptr
    }
}

// ── 문자열 읽기 헬퍼 ─────────────────────────
unsafe fn read_str(ptr: *const u8, len: usize) -> &'static str {
    let slice = std::slice::from_raw_parts(ptr, len);
    std::str::from_utf8_unchecked(slice)
}

// ── FV-Lang 코드 평가 ────────────────────────
#[no_mangle]
pub extern "C" fn eval_fv_raw(ptr: *const u8, len: usize) -> *mut u8 {
    let code = unsafe { read_str(ptr, len) };
    let result = run_fv(code);
    write_result(&result)
}

// ── AST 파싱 ────────────────────────────────
#[no_mangle]
pub extern "C" fn parse_to_ast_raw(ptr: *const u8, len: usize) -> *mut u8 {
    let code = unsafe { read_str(ptr, len) };
    let ast = parse_ast(code);
    write_result(&ast)
}

// ── 버전 문자열 (null 종료) ───────────────────
#[no_mangle]
pub extern "C" fn fv_version_raw() -> *const u8 {
    b"FV-Lang 0.1.0 (WASM)\0".as_ptr()
}

// ── 내부 구현 ────────────────────────────────
fn run_fv(code: &str) -> String {
    let lexer = match fv_lang::Lexer::new(code) {
        Ok(l) => l,
        Err(e) => return format!(r#"{{"success":false,"error":"Lexer 오류: {}"}}"#, e),
    };
    let tokens = match lexer.tokenize() {
        Ok(t) => t,
        Err(e) => return format!(r#"{{"success":false,"error":"토큰 오류: {}"}}"#, e),
    };
    let parser = match fv_lang::Parser::new(tokens) {
        Ok(p) => p,
        Err(e) => return format!(r#"{{"success":false,"error":"파서 초기화 오류: {}"}}"#, e),
    };
    let ast = match parser.parse() {
        Ok(a) => a,
        Err(e) => return format!(r#"{{"success":false,"error":"파싱 오류: {}"}}"#, e),
    };
    match fv_lang::CodeGenerator::new().generate(&ast) {
        Ok(out) => format!(r#"{{"success":true,"output":{}}}"#, json_str(&out)),
        Err(e)  => format!(r#"{{"success":false,"error":"컴파일 오류: {}"}}"#, e),
    }
}

fn parse_ast(code: &str) -> String {
    let lexer = match fv_lang::Lexer::new(code) {
        Ok(l) => l,
        Err(e) => return format!(r#"{{"error":"{}"}}"#, e),
    };
    let tokens = match lexer.tokenize() {
        Ok(t) => t,
        Err(e) => return format!(r#"{{"error":"{}"}}"#, e),
    };
    let parser = match fv_lang::Parser::new(tokens) {
        Ok(p) => p,
        Err(e) => return format!(r#"{{"error":"{}"}}"#, e),
    };
    match parser.parse() {
        Ok(ast) => format!("{:#?}", ast),
        Err(e)  => format!(r#"{{"error":"{}"}}"#, e),
    }
}

fn json_str(s: &str) -> String {
    format!("\"{}\"", s.replace('\\', "\\\\").replace('"', "\\\"").replace('\n', "\\n"))
}

