     1→/**
     2→ * FreeWire Phase 7 — Repair Engine
     3→ *
     4→ * 위반(Violation)을 받아서 최소한의 그래프 패치를 생성한다.
     5→ * 전체를 재생성하지 않고, 필요한 부분만 수술한다.
     6→ *
     7→ * 패치 타입:
     8→ *   add_wire    — 두 노드를 연결하는 와이어 추가
     9→ *   add_node    — 누락된 노드 추가 (+ 자동 위치 계산)
    10→ *   fix_prop    — 노드의 props 수정
    11→ *   remove_node — 의미 없는 노드 제거 (고아 노드)
    12→ */
    13→
    14→'use strict';
    15→
    16→let _repairIdCtr = 1;
    17→const rid = () => `rp-${_repairIdCtr++}`;
    18→
    19→// ─── 패치 구조 ─────────────────────────────────────────────────
    20→
    21→class GraphPatch {
    22→  constructor({ type, description, confidence, apply }) {
    23→    this.id          = rid();
    24→    this.type        = type;        // 'add_wire' | 'add_node' | 'fix_prop' | 'remove_node'
    25→    this.description = description; // 사람이 읽을 수 있는 설명
    26→    this.confidence  = confidence;  // 0-1, 이 패치가 맞을 확률
    27→    this._apply      = apply;       // (nodes, wires) => void
    28→  }
    29→
    30→  apply(nodes, wires) {
    31→    this._apply(nodes, wires);
    32→    return this;
    33→  }
    34→}
    35→
    36→// ─── Repair Engine ─────────────────────────────────────────────
    37→
    38→class RepairEngine {
    39→  /**
    40→   * 위반 목록 → 패치 목록 (신뢰도 순 정렬)
    41→   * @param {ContractViolation[]} violations
    42→   * @param {Map} nodes
    43→   * @param {Map} wires
    44→   * @returns {GraphPatch[]}
    45→   */
    46→  suggest(violations, nodes, wires) {
    47→    const nodesArr = [...nodes.values()].map(v => v.def ?? v);
    48→    const wiresArr = [...wires.values()];
    49→    const patches  = [];
    50→
    51→    // 구조적 경고도 수리 대상 (state 바인딩 등)
    52→    const FIXABLE_WARNINGS = new Set(['wire_state_to_display', 'connect_orphan']);
    53→
    54→    for (const v of violations) {
    55→      if (v.severity !== 'error' && !FIXABLE_WARNINGS.has(v.repairHint)) continue;
    56→
    57→      const p = this._violationToPatch(v, nodesArr, wiresArr);
    58→      if (p) patches.push(p);
    59→    }
    60→
    61→    // 신뢰도 높은 것 먼저, 중복 제거
    62→    return this._deduplicate(patches).sort((a, b) => b.confidence - a.confidence);
    63→  }
    64→
    65→  /**
    66→   * 패치들을 실제 그래프에 적용
    67→   * @param {GraphPatch[]} patches
    68→   * @param {Map} nodes
    69→   * @param {Map} wires
    70→   * @param {Function} nextId - ID 생성기
    71→   * @returns {{ applied: GraphPatch[], skipped: GraphPatch[] }}
    72→   */
    73→  applyPatches(patches, nodes, wires, nextId) {
    74→    const applied = [], skipped = [];
    75→
    76→    for (const patch of patches) {
    77→      try {
    78→        patch.apply(nodes, wires, nextId);
    79→        applied.push(patch);
    80→      } catch (e) {
    81→        skipped.push({ patch, reason: e.message });
    82→      }
    83→    }
    84→
    85→    return { applied, skipped };
    86→  }
    87→
    88→  // ─── 위반 → 패치 매핑 ──────────────────────────────────────
    89→
    90→  _violationToPatch(violation, nodesArr, wiresArr) {
    91→    const { repairHint, fact, nodeId, type } = violation;
    92→
    93→    // 버튼 ↔ 핸들러 연결 누락
    94→    if (repairHint === 'wire_handler_to_button' || fact === 'ui.button.connected') {
    95→      return this._patchWireHandlerToButton(nodeId, nodesArr, wiresArr);
    96→    }
    97→
    98→    // 핸들러 노드 자체가 없음
    99→    if (repairHint === 'add_handler_node' || fact === 'action.handler.present') {
   100→      return this._patchAddHandlerNode(nodesArr);
   101→    }
   102→
   103→    // state ↔ 텍스트 바인딩 누락
   104→    if (repairHint === 'wire_state_to_display' || fact === 'state.bound') {
