/**
 * FreeWire Phase 7 — Repair Engine
 *
 * 위반(Violation)을 받아서 최소한의 그래프 패치를 생성한다.
 * 전체를 재생성하지 않고, 필요한 부분만 수술한다.
 *
 * 패치 타입:
 *   add_wire    — 두 노드를 연결하는 와이어 추가
 *   add_node    — 누락된 노드 추가 (+ 자동 위치 계산)
 *   fix_prop    — 노드의 props 수정
 *   remove_node — 의미 없는 노드 제거 (고아 노드)
 */

'use strict';

let _repairIdCtr = 1;
const rid = () => `rp-${_repairIdCtr++}`;

// ─── 패치 구조 ─────────────────────────────────────────────────

class GraphPatch {
  constructor({ type, description, confidence, apply }) {
    this.id          = rid();
    this.type        = type;        // 'add_wire' | 'add_node' | 'fix_prop' | 'remove_node'
    this.description = description; // 사람이 읽을 수 있는 설명
    this.confidence  = confidence;  // 0-1, 이 패치가 맞을 확률
    this._apply      = apply;       // (nodes, wires) => void
  }

  apply(nodes, wires) {
    this._apply(nodes, wires);
    return this;
  }
}

// ─── Repair Engine ─────────────────────────────────────────────

class RepairEngine {
  /**
   * 위반 목록 → 패치 목록 (신뢰도 순 정렬)
   * @param {ContractViolation[]} violations
   * @param {Map} nodes
   * @param {Map} wires
   * @returns {GraphPatch[]}
   */
  suggest(violations, nodes, wires) {
    const nodesArr = [...nodes.values()].map(v => v.def ?? v);
    const wiresArr = [...wires.values()];
    const patches  = [];

    // 구조적 경고도 수리 대상 (state 바인딩 등)
    const FIXABLE_WARNINGS = new Set(['wire_state_to_display', 'connect_orphan']);

    for (const v of violations) {
      if (v.severity !== 'error' && !FIXABLE_WARNINGS.has(v.repairHint)) continue;

      const p = this._violationToPatch(v, nodesArr, wiresArr);
      if (p) patches.push(p);
    }

    // 신뢰도 높은 것 먼저, 중복 제거
    return this._deduplicate(patches).sort((a, b) => b.confidence - a.confidence);
  }

  /**
   * 패치들을 실제 그래프에 적용
   * @param {GraphPatch[]} patches
   * @param {Map} nodes
   * @param {Map} wires
   * @param {Function} nextId - ID 생성기
   * @returns {{ applied: GraphPatch[], skipped: GraphPatch[] }}
   */
  applyPatches(patches, nodes, wires, nextId) {
    const applied = [], skipped = [];

    for (const patch of patches) {
      try {
        patch.apply(nodes, wires, nextId);
        applied.push(patch);
      } catch (e) {
        skipped.push({ patch, reason: e.message });
      }
    }

    return { applied, skipped };
  }

  // ─── 위반 → 패치 매핑 ──────────────────────────────────────

  _violationToPatch(violation, nodesArr, wiresArr) {
    const { repairHint, fact, nodeId, type } = violation;

    // 버튼 ↔ 핸들러 연결 누락
    if (repairHint === 'wire_handler_to_button' || fact === 'ui.button.connected') {
      return this._patchWireHandlerToButton(nodeId, nodesArr, wiresArr);
    }

    // 핸들러 노드 자체가 없음
    if (repairHint === 'add_handler_node' || fact === 'action.handler.present') {
      return this._patchAddHandlerNode(nodesArr);
    }

    // state ↔ 텍스트 바인딩 누락
    if (repairHint === 'wire_state_to_display' || fact === 'state.bound') {
      return this._patchWireStateToDisplay(nodeId, nodesArr, wiresArr);
    }

    // 고아 노드 연결
    if (repairHint === 'connect_orphan' || fact === 'node.connected') {
      return this._patchConnectOrphan(nodeId, nodesArr, wiresArr);
    }

    // Goal fact 관련 수정
    if (type === 'goal') return this._patchForGoalFact(fact, nodesArr, wiresArr);

    // requires 미충족
    if (type === 'requires') return this._patchRequires(violation, nodesArr, wiresArr);

    return null;
  }

  _patchWireHandlerToButton(buttonId, nodesArr, wiresArr) {
    const handlers = nodesArr.filter(n => n.subtype === 'handler');
    if (handlers.length === 0) return null;

    const handler = handlers[0];
    return new GraphPatch({
      type: 'add_wire',
      description: `핸들러 "${handler.label}"를 버튼에 연결 (onClick 포트)`,
      confidence: 0.9,
      apply: (nodes, wires, nextId) => {
        const wireId = nextId ? nextId() : `rw-${Date.now()}`;
        wires.set(wireId, {
          id: wireId,
          fn: handler.id, fp: 0,  // handler의 output[0]
          tn: buttonId,   tp: 1,  // button의 input[1] (onClick)
        });
      },
    });
  }

  _patchAddHandlerNode(nodesArr) {
    const buttons = nodesArr.filter(n => n.subtype === 'button');
    if (buttons.length === 0) return null;

    const lastBtn = buttons[buttons.length - 1];
    const handlerName = this._guessHandlerName(lastBtn);
    const newId = `handler-${Date.now()}`;

    // 버튼 오른쪽에 배치
    const bx = lastBtn.position?.x ?? 300;
    const by = lastBtn.position?.y ?? 200;

    return new GraphPatch({
      type: 'add_node',
      description: `이벤트 핸들러 "${handlerName}" 추가`,
      confidence: 0.85,
      apply: (nodes, wires, nextId) => {
        const nid = nextId ? nextId() : newId;
        nodes.set(nid, {
          id: nid, type: 'logic', subtype: 'handler', label: `핸들러[${handlerName}]`,
          inputs:  [{ name: 'action', portType: 'logic' }],
          outputs: [{ name: 'handler', portType: 'logic' }],
          props: { name: handlerName },
          intent: '이벤트 처리',
          contract: {
            requires: [], ensures: ['action.handler.present', 'ui.button.connected'],
            produces: ['action.handler.present', 'ui.button.connected'], warns: [],
          },
          position: { x: bx + 230, y: by },
        });

        // 버튼에 자동 연결
        const wireId = nextId ? nextId() : `rw-${Date.now()}`;
        wires.set(wireId, { id: wireId, fn: nid, fp: 0, tn: lastBtn.id, tp: 1 });
      },
    });
  }

  _patchWireStateToDisplay(stateId, nodesArr, wiresArr) {
    if (!stateId) return null;
    const textNodes = nodesArr.filter(n => n.subtype === 'text');
    if (textNodes.length === 0) return null;

    // 아직 연결 안 된 텍스트 찾기
    const unbound = textNodes.find(t =>
      !wiresArr.some(w => (w.tn ?? w.to) === t.id && (w.fn ?? w.from) === stateId)
    );
    if (!unbound) return null;

    return new GraphPatch({
      type: 'add_wire',
      description: `상태를 텍스트 "${unbound.label}"에 바인딩`,
      confidence: 0.8,
      apply: (nodes, wires, nextId) => {
        const wireId = nextId ? nextId() : `rw-${Date.now()}`;
        wires.set(wireId, { id: wireId, fn: stateId, fp: 0, tn: unbound.id, tp: 0 });
      },
    });
  }

  _patchConnectOrphan(orphanId, nodesArr, wiresArr) {
    const orphan = nodesArr.find(n => n.id === orphanId);
    if (!orphan) return null;

    // 컨테이너나 카드를 찾아서 연결
    const container = nodesArr.find(n =>
      n.subtype === 'container' || n.subtype === 'card'
    );
    if (!container) return null;

    return new GraphPatch({
      type: 'add_wire',
      description: `고아 노드 "${orphan.label}"를 컨테이너에 연결`,
      confidence: 0.65,
      apply: (nodes, wires, nextId) => {
        const wireId = nextId ? nextId() : `rw-${Date.now()}`;
        wires.set(wireId, { id: wireId, fn: orphanId, fp: 0, tn: container.id, tp: 0 });
      },
    });
  }

  _patchForGoalFact(fact, nodesArr, wiresArr) {
    // 목표 fact에 따라 누락된 노드 제안
    if (fact === 'auth.initiated' || fact === 'form.email.filled') {
      const hasEmailInput = nodesArr.some(n =>
        n.subtype === 'input' && n.props?.type === 'email'
      );
      if (!hasEmailInput) {
        return new GraphPatch({
          type: 'add_node',
          description: '이메일 입력 필드 추가 (로그인에 필요)',
          confidence: 0.75,
          apply: (nodes, wires, nextId) => {
            const nid = nextId ? nextId() : `email-${Date.now()}`;
            nodes.set(nid, {
              id: nid, type: 'component', subtype: 'input', label: '입력[이메일]',
              inputs: [{ name: 'value', portType: 'data' }, { name: 'onChange', portType: 'logic' }],
              outputs: [{ name: 'element', portType: 'component' }, { name: 'value', portType: 'data' }],
              props: { placeholder: '이메일', type: 'email' },
              intent: '이메일 수집',
              contract: {
                requires: [], ensures: ['form.email.filled', 'data.available'],
                produces: ['form.email.filled', 'data.available'], warns: [],
              },
              position: { x: 120, y: 120 },
            });
          },
        });
      }
    }

    if (fact === 'state.bound') {
      return this._patchWireStateToDisplay(
        nodesArr.find(n => n.subtype === 'state')?.id,
        nodesArr, wiresArr
      );
    }

    return null;
  }

  _patchRequires(violation, nodesArr, wiresArr) {
    const { fact, nodeId } = violation;

    // data.available이 필요한 경우 → state나 input 연결 찾기
    if (fact === 'data.available') {
      const dataNode = nodesArr.find(n => n.type === 'data');
      const targetNode = nodesArr.find(n => n.id === nodeId);
      if (!dataNode || !targetNode) return null;

      return new GraphPatch({
        type: 'add_wire',
        description: `데이터 소스 "${dataNode.label}"를 "${targetNode.label}"에 연결`,
        confidence: 0.7,
        apply: (nodes, wires, nextId) => {
          const wireId = nextId ? nextId() : `rw-${Date.now()}`;
          wires.set(wireId, { id: wireId, fn: dataNode.id, fp: 0, tn: nodeId, tp: 0 });
        },
      });
    }

    return null;
  }

  // ─── 헬퍼 ────────────────────────────────────────────────────

  _guessHandlerName(btn) {
    const label = (btn.props?.label ?? '').toLowerCase();
    if (/로그인|login/.test(label))  return 'handleLogin';
    if (/\+|증가|inc/.test(label))   return 'handleIncrement';
    if (/-|감소|dec/.test(label))    return 'handleDecrement';
    if (/초기화|reset/.test(label))  return 'handleReset';
    if (/제출|submit/.test(label))   return 'handleSubmit';
    if (/검색|search/.test(label))   return 'handleSearch';
    if (/추가|add/.test(label))      return 'handleAdd';
    if (/삭제|del|remove/.test(label)) return 'handleDelete';
    return 'handleClick';
  }

  _deduplicate(patches) {
    const seen = new Set();
    return patches.filter(p => {
      const key = `${p.type}:${p.description}`;
      if (seen.has(key)) return false;
      seen.add(key);
      return true;
    });
  }
}

module.exports = { RepairEngine, GraphPatch };

