/**
 * FreeWire - Graph → FreeLang Light 컴파일러
 * 노드 그래프 JSON → 완성된 .free 파일 문자열 생성
 */

const { Graph }              = require('../core/graph');
const { toFreelangMarkup }   = require('../core/nodes/component');
const { toFreelangCode: dataToCode }  = require('../core/nodes/data');
const { toFreelangCode: logicToCode } = require('../core/nodes/logic');

class GraphCompiler {
  constructor() {
    this.errors   = [];
    this.warnings = [];
  }

  /**
   * Graph 인스턴스 또는 JSON → .free 파일 문자열
   * @param {Graph|object} input
   * @returns {{ code: string, errors: string[], warnings: string[] }}
   */
  compile(input) {
    this.errors   = [];
    this.warnings = [];

    const graph = input instanceof Graph ? input : Graph.fromJSON(input);
    const sorted = graph.topologicalSort();

    const propsNodes     = sorted.filter(n => n.type === 'data' && n.dataType === 'props');
    const stateNodes     = sorted.filter(n => n.type === 'data' && n.dataType === 'state');
    const constNodes     = sorted.filter(n => n.type === 'data' && !['props','state'].includes(n.dataType));
    const logicNodes     = sorted.filter(n => n.type === 'logic');
    const componentNodes = sorted.filter(n => n.type === 'component');

    if (componentNodes.length === 0) {
      this.warnings.push('component 노드가 없습니다. markup 블록이 비어 있습니다.');
    }

    // 컴포넌트 이름: 그래프 id 또는 첫 component 이름
    const compName = this._resolveComponentName(graph, componentNodes);

    const sections = [];

    // 1) component 헤더
    sections.push(`component ${compName} {`);

    // 2) props 블록
    const propsBlock = this._buildPropsBlock(propsNodes);
    if (propsBlock) sections.push(propsBlock);

    // 3) style 블록 (component props에서 수집)
    const styleBlock = this._buildStyleBlock(componentNodes);
    if (styleBlock) sections.push(styleBlock);

    // 4) script 블록 (state + const + logic)
    const scriptBlock = this._buildScriptBlock(stateNodes, constNodes, logicNodes, graph);
    if (scriptBlock) sections.push(scriptBlock);

    // 5) markup 블록
    const markupBlock = this._buildMarkupBlock(componentNodes, graph);
    sections.push(markupBlock);

    sections.push('}');

    return {
      code:     sections.join('\n\n'),
      errors:   this.errors,
      warnings: this.warnings,
    };
  }

  // ─── 내부 빌더 ──────────────────────────────────────────────

  _resolveComponentName(graph, componentNodes) {
    if (componentNodes.length > 0 && componentNodes[0].props?.name) {
      return componentNodes[0].props.name;
    }
    return graph.id.replace(/[^a-zA-Z0-9]/g, '_') || 'MyComponent';
  }

  _buildPropsBlock(propsNodes) {
    if (propsNodes.length === 0) return null;
    const lines = propsNodes.map(n => {
      const { name, value, required } = n.props;
      const req = required ? '' : `= ${JSON.stringify(value)}`;
      return `  ${name}: ${n.dataType} ${req}`.trimEnd() + ';';
    });
    return `  props {\n${lines.join('\n')}\n  }`;
  }

  _buildStyleBlock(componentNodes) {
    const styleLines = [];
    componentNodes.forEach(n => {
      const p = n.props;
      const selector = `.${n.componentType}`;
      const rules = [];

      if (p.color)        rules.push(`color: ${p.color}`);
      if (p.background)   rules.push(`background: ${p.background}`);
      if (p.padding)      rules.push(`padding: ${p.padding}`);
      if (p.gap)          rules.push(`gap: ${p.gap}`);
      if (p.fontSize)     rules.push(`font-size: ${p.fontSize}`);
      if (p.borderRadius) rules.push(`border-radius: ${p.borderRadius}`);
      if (p.direction && n.componentType === 'container') {
        rules.push(`display: flex`);
        rules.push(`flex-direction: ${p.direction}`);
      }

      if (rules.length > 0) {
        styleLines.push(`  ${selector} {`);
        rules.forEach(r => styleLines.push(`    ${r};`));
        styleLines.push(`  }`);
      }
    });

    if (styleLines.length === 0) return null;
    return `  style {\n${styleLines.join('\n')}\n  }`;
  }

  _buildScriptBlock(stateNodes, constNodes, logicNodes, graph) {
    const lines = [];

    // 상수
    constNodes.forEach(n => {
      lines.push(`  let ${n.props.name} = ${JSON.stringify(n.props.value)};`);
    });

    // 상태
    stateNodes.forEach(n => {
      lines.push(`  let ${n.props.name} = ${JSON.stringify(n.props.value)};`);
      lines.push(`  function set_${n.props.name}(v) { ${n.props.name} = v; }`);
    });

    // 로직 노드 (연결 정보 포함)
    logicNodes.forEach(n => {
      const code = this._logicNodeToScript(n, graph);
      if (code) lines.push(code);
    });

    if (lines.length === 0) return null;
    return `  script {\n${lines.join('\n')}\n  }`;
  }

  _logicNodeToScript(node, graph) {
    const { logicType, props } = node;

    // 입력 연결에서 실제 값/노드 id 추론
    const inEdges = graph.incomingEdges(node.id);
    const getConnected = (portId) => {
      const e = inEdges.find(e => e.to.portId === portId);
      return e ? e.from.nodeId : null;
    };

    switch (logicType) {
      case 'if': {
        const cond = props.condition || getConnected('condition') || 'true';
        return [
          `  if (${cond}) {`,
          `    // then: ${getConnected('then') || '연결 없음'}`,
          `  } else {`,
          `    // else: ${getConnected('else') || '연결 없음'}`,
          `  }`,
        ].join('\n');
      }
      case 'function':
        return [
          `  function ${props.name}(${(props.params || []).join(', ')}) {`,
          `    ${props.body || 'return null;'}`,
          `  }`,
        ].join('\n');
      case 'map':
        return `  let ${node.id}_result = (${getConnected('array') || '[]'}).map(function(${props.itemName}) { return ${props.expression}; });`;
      case 'filter':
        return `  let ${node.id}_result = (${getConnected('array') || '[]'}).filter(function(${props.itemName}) { return ${props.condition}; });`;
      case 'reduce':
        return `  let ${node.id}_result = (${getConnected('array') || '[]'}).reduce(function(${props.accumName}, ${props.itemName}) { return ${props.expression}; }, ${props.initial});`;
      case 'loop':
        return null; // markup 블록에서 처리
      default:
        this.warnings.push(`알 수 없는 logicType: ${logicType}`);
        return null;
    }
  }

  _buildMarkupBlock(componentNodes, graph) {
    if (componentNodes.length === 0) {
      return `  markup {\n    <!-- 컴포넌트 없음 -->\n  }`;
    }

    // 루트 컴포넌트: 다른 노드의 출력을 받지 않는 component
    const childIds = new Set(
      graph.edges
        .filter(e => e.to.portId === 'children' || e.from.portType === 'component')
        .map(e => e.to.nodeId)
    );
    const roots = componentNodes.filter(n => !childIds.has(n.id));
    const renderTargets = roots.length > 0 ? roots : [componentNodes[0]];

    const lines = ['  markup {'];
    renderTargets.forEach(n => {
      const markup = toFreelangMarkup(n);
      // 들여쓰기 맞추기
      markup.split('\n').forEach(line => {
        lines.push('  ' + line);
      });
    });
    lines.push('  }');
    return lines.join('\n');
  }
}

module.exports = { GraphCompiler };

