pub extern "C" fn result_total_size(ptr: *const u8) -> usize {
    let len = unsafe {
        let mut b = [0u8; 4];
        std::ptr::copy_nonoverlapping(ptr, b.as_mut_ptr(), 4);
        u32::from_le_bytes(b) as usize
    };
    4 + len
}

