topologicalSort() {
  const visited = new Set();
  const onStack = new Set(); // 사이클 감지용
  const order   = [];

  const visit = (nodeId) => {
    if (visited.has(nodeId)) return;
    if (onStack.has(nodeId)) {
      // 사이클 감지: 이 노드는 건너뜀 (순환 의존)
      return;
    }
    onStack.add(nodeId);
    this.incomingEdges(nodeId).forEach(e => visit(e.from.nodeId));
    onStack.delete(nodeId);
    visited.add(nodeId);
    order.push(nodeId);
  };

  this.nodes.forEach(n => visit(n.id));
  return order.map(id => this.getNode(id));
}

