/**
 * FreeWire Phase 9 — Contract Inferrer
 *
 * "사람이 contract를 직접 안 써도 된다"
 *
 * 노드의 subtype + goal text + 연결된 와이어 구조를 보고
 * requires / ensures / produces / warns 를 자동으로 추론한다.
 *
 * 추론 방법:
 *   1. Subtype 기반 기본 템플릿 (intent-spec의 defaults 확장)
 *   2. Goal text NLP: 키워드 → facts 매핑
 *   3. 구조 분석: 연결된 노드 조합 → 추가 facts
 *   4. 이력 보정: 과거에 자주 필요했던 facts 추가
 */

'use strict';

const { NODE_INTENT_DEFAULTS, parseGoalToFacts } = require('./intent-spec');

// ─── 추론 결과 ───────────────────────────────────────────────

class InferredContract {
  constructor({ requires, ensures, produces, warns, confidence, sources }) {
    this.requires   = requires   ?? [];
    this.ensures    = ensures    ?? [];
    this.produces   = produces   ?? [];
    this.warns      = warns      ?? [];
    this.confidence = confidence ?? 0.7; // 0-1, 추론 신뢰도
    this.sources    = sources    ?? [];  // ['subtype_template', 'goal_text', 'structure']
  }
}

// ─── Contract Inferrer ──────────────────────────────────────

class ContractInferrer {
  constructor(history = null) {
    this._history = history;
  }

  /**
   * 단일 노드의 contract 추론
   * @param {object} node        - 노드 정의
   * @param {object[]} allNodes  - 전체 노드 배열 (구조 분석용)
   * @param {object[]} wires     - 전체 와이어 배열
   * @param {string} goalText    - 사용자 의도 텍스트
   */
  infer(node, allNodes = [], wires = [], goalText = '') {
    const sources = [];
    let requires = new Set();
    let ensures  = new Set();
    let produces = new Set();
    let warns    = new Set();
    let confidence = 0.5;

    // 1) Subtype 기본 템플릿
    const template = NODE_INTENT_DEFAULTS[node.subtype];
    if (template?.contract) {
      for (const f of (template.contract.requires ?? []))  requires.add(f);
      for (const f of (template.contract.ensures  ?? []))  ensures.add(f);
      for (const f of (template.contract.produces ?? []))  produces.add(f);
      for (const f of (template.contract.warns    ?? []))  warns.add(f);
      confidence += 0.2;
      sources.push('subtype_template');
    }

    // 2) 노드 props 분석
    this._inferFromProps(node, requires, ensures, produces, warns);
    sources.push('props_analysis');

    // 3) Goal text 분석
    if (goalText) {
      const goalFacts = parseGoalToFacts(goalText);
      const relevant  = this._filterRelevantFacts(node.subtype, goalFacts);
      for (const f of relevant) produces.add(f);
      if (relevant.length > 0) {
        confidence += 0.1;
        sources.push('goal_text');
      }
    }

    // 4) 연결 구조 분석
    const structureFacts = this._inferFromStructure(node, allNodes, wires);
    for (const f of structureFacts.requires) requires.add(f);
    for (const f of structureFacts.produces) produces.add(f);
    for (const f of structureFacts.warns)    warns.add(f);
    if (structureFacts.requires.length + structureFacts.produces.length > 0) {
      confidence += 0.1;
      sources.push('structure');
    }

    // 5) 이력 보정 (있는 경우)
    if (this._history) {
      const histFacts = this._inferFromHistory(node.subtype);
      for (const f of histFacts) warns.add(f);
      if (histFacts.length > 0) {
        confidence = Math.min(confidence + 0.05, 1.0);
        sources.push('history');
      }
    }

    return new InferredContract({
      requires: [...requires],
      ensures:  [...ensures],
      produces: [...produces],
      warns:    [...warns],
      confidence: Math.min(confidence, 1.0),
      sources,
    });
  }

  /**
   * 그래프 전체 nodes에 contract 자동 주입
   * contract가 없거나 비어있는 노드에만 적용
   */
  inferAll(nodes, wires, goalText = '') {
    const nodesArr = [...nodes.values()].map(v => v.def ?? v);
    const wiresArr = [...wires.values()];
    const results  = new Map();

    for (const node of nodesArr) {
      const hasContract = node.contract &&
        (node.contract.requires?.length > 0 || node.contract.produces?.length > 0);

      if (!hasContract) {
        const inferred = this.infer(node, nodesArr, wiresArr, goalText);
        results.set(node.id, inferred);
      }
    }

    return results; // Map<nodeId, InferredContract>
  }

  // ─── 내부 추론 로직 ──────────────────────────────────────

  _inferFromProps(node, requires, ensures, produces, warns) {
    const props = node.props ?? {};
    const type  = node.subtype;

    if (type === 'input') {
      if (props.type === 'email')    produces.add('form.email.filled');
      if (props.type === 'password') produces.add('form.password.filled');
      if (props.type === 'text')     produces.add('data.available');
      if (props.required)            ensures.add('form.field.required');
    }

    if (type === 'button') {
      const label = (props.label ?? '').toLowerCase();
      if (/로그인|login/.test(label))   produces.add('auth.initiated');
      if (/제출|submit/.test(label))    produces.add('form.submitted');
      if (/검색|search/.test(label))    produces.add('search.initiated');
      if (/증가|\\+|inc/.test(label))   produces.add('counter.incremented');
      if (/감소|-|dec/.test(label))     produces.add('counter.decremented');
      if (/추가|add/.test(label))       produces.add('item.added');
      if (/삭제|remove|del/.test(label))produces.add('item.removed');
    }

    if (type === 'state') {
      const name = (props.name ?? '').toLowerCase();
      if (/count|카운트/.test(name))   produces.add('counter.state.available');
      if (/user|사용자/.test(name))    produces.add('user.state.available');
      if (/list|목록/.test(name))      produces.add('list.state.available');
      produces.add('state.available');
    }

    if (type === 'handler') {
      const name = (props.name ?? '').toLowerCase();
      if (/login|로그인/.test(name))   ensures.add('auth.handler.ready');
      if (/submit|제출/.test(name))    ensures.add('form.handler.ready');
      requires.add('action.triggered');
    }

    if (type === 'text') {
      warns.add('state.bound'); // 텍스트는 보통 상태와 연결돼야 함
    }

    if (type === 'container' || type === 'card') {
      ensures.add('layout.structured');
    }
  }

  _filterRelevantFacts(subtype, goalFacts) {
    // subtype과 관련 있을 법한 goal facts만 필터
    const SUBTYPE_FACT_AFFINITY = {
      button:    ['auth.initiated', 'form.submitted', 'search.initiated', 'counter.incremented'],
      input:     ['form.email.filled', 'form.password.filled', 'data.available'],
      state:     ['state.bound', 'counter.state.available'],
      handler:   ['auth.handler.ready', 'form.handler.ready', 'action.handler.present'],
      text:      ['state.bound', 'data.displayed'],
      container: ['layout.structured'],
    };

    const affinities = new Set(SUBTYPE_FACT_AFFINITY[subtype] ?? []);
    return goalFacts.filter(f => affinities.has(f));
  }

  _inferFromStructure(node, allNodes, wires) {
    const requires = [];
    const produces = [];
    const warns    = [];

    // 이 노드의 입력 연결
    const inputWires  = wires.filter(w => (w.tn ?? w.to) === node.id);
    // 이 노드의 출력 연결
    const outputWires = wires.filter(w => (w.fn ?? w.from) === node.id);

    // 연결된 소스 노드들의 subtype
    const sourceSubs = inputWires
      .map(w => allNodes.find(n => n.id === (w.fn ?? w.from))?.subtype)
      .filter(Boolean);

    // 연결된 타겟 노드들의 subtype
    const targetSubs = outputWires
      .map(w => allNodes.find(n => n.id === (w.tn ?? w.to))?.subtype)
      .filter(Boolean);

    // 구조 패턴 기반 facts 추론
    if (node.subtype === 'handler') {
      if (sourceSubs.includes('button')) produces.push('ui.button.connected');
      if (targetSubs.includes('state'))  produces.push('state.mutation.possible');
    }

    if (node.subtype === 'state') {
      if (targetSubs.includes('text'))   produces.push('state.bound');
      if (sourceSubs.includes('handler'))requires.push('action.handler.present');
    }

    if (node.subtype === 'button') {
      if (!sourceSubs.includes('handler') && allNodes.some(n => n.subtype === 'handler')) {
        warns.push('ui.button.connected');
      }
    }

    return { requires, produces, warns };
  }

  _inferFromHistory(subtype) {
    if (!this._history) return [];

    // 이 subtype에서 자주 경고됐던 facts
    const top = this._history.topViolations(10);
    return top
      .filter(v => v.pattern.startsWith(`${subtype}:`))
      .map(v => v.pattern.split(':')[1])
      .filter(Boolean);
  }
}

// ─── 인라인 사용 헬퍼 ───────────────────────────────────────

/**
 * 노드에 inferred contract를 머지
 * 기존 contract를 유지하면서 비어있는 필드만 채움
 */
function mergeInferredContract(node, inferred) {
  const existing = node.contract ?? {};
  return {
    ...node,
    contract: {
      requires: existing.requires?.length ? existing.requires : inferred.requires,
      ensures:  existing.ensures?.length  ? existing.ensures  : inferred.ensures,
      produces: existing.produces?.length ? existing.produces : inferred.produces,
      warns:    existing.warns?.length    ? existing.warns    : inferred.warns,
      _inferred: true,
      _confidence: inferred.confidence,
      _sources:    inferred.sources,
    },
  };
}

module.exports = { ContractInferrer, InferredContract, mergeInferredContract };

