/**
 * FreeWire Phase 7 — Self-Correct Loop
 *
 * 루프가 닫힌다.
 *
 * 생성 → 평가 → [score < 100?] → 수리 → 재평가 → ...
 *         ↑__________________________________|
 *
 * 이 루프가 돌 때 사람은 개입하지 않는다.
 * 시스템이 스스로 의도에 근접해간다.
 */

'use strict';

const { IntentEvaluator } = require('./evaluator');
const { RepairEngine }    = require('./repair-engine');

class SelfCorrectLoop {
  constructor({ maxIterations = 3, targetScore = 85 } = {}) {
    this.maxIterations = maxIterations;
    this.targetScore   = targetScore;
    this.evaluator     = new IntentEvaluator();
    this.repair        = new RepairEngine();
  }

  /**
   * 단 하나의 공개 메서드.
   * 목표 텍스트와 그래프를 받아서, 자기 수정 루프를 돌린다.
   *
   * @param {string} goal    - 사용자 원래 의도
   * @param {Map}    nodes   - 현재 노드 맵 (mutable)
   * @param {Map}    wires   - 현재 와이어 맵 (mutable)
   * @param {Function} nextId - ID 생성기
   * @returns {LoopResult}
   */
  run(goal, nodes, wires, nextId = defaultNextId()) {
    const trace = [];
    let iteration = 0;
    let lastReport = null;

    while (iteration < this.maxIterations) {
      iteration++;

      // 1) 평가
      const report = this.evaluator.evaluate(nodes, wires, goal);
      lastReport = report;

      trace.push({
        iteration,
        score:      report.score,
        errors:     report.errors.length,
        warnings:   report.warnings.length,
        patches:    [],
        summary:    report.summary,
      });

      // 목표 달성
      if (report.passed && report.score >= this.targetScore) {
        break;
      }

      // 오류 없음 (경고만)
      if (report.errors.length === 0) {
        break;
      }

      // 2) 수리 패치 생성
      const patches = this.repair.suggest(report.violations, nodes, wires);
      if (patches.length === 0) break; // 수리 방법 없음

      // 3) 패치 적용
      const { applied } = this.repair.applyPatches(patches, nodes, wires, nextId);
      trace[trace.length - 1].patches = applied.map(p => ({
        type: p.type, description: p.description, confidence: p.confidence,
      }));

      if (applied.length === 0) break; // 아무것도 적용 안 됨 (무한루프 방지)
    }

    return {
      goal,
      iterations:    iteration,
      converged:     lastReport?.passed ?? false,
      finalScore:    lastReport?.score  ?? 0,
      trace,
      finalReport:   lastReport,
      improved:      trace.length > 1
        ? (trace[trace.length - 1].score > trace[0].score)
        : false,
    };
  }
}

// ─── 단일 평가만 (루프 없이) ────────────────────────────────────

function evaluateOnce(goal, nodes, wires) {
  const evaluator = new IntentEvaluator();
  return evaluator.evaluate(nodes, wires, goal);
}

// ─── ID 생성기 팩토리 ───────────────────────────────────────────

function defaultNextId() {
  let ctr = Date.now();
  return () => `rc-${ctr++}`;
}

module.exports = { SelfCorrectLoop, evaluateOnce, defaultNextId };

/**
 * FreeWire Phase 7 — Intent as First Class Citizen
 *
 * 노드는 더 이상 "무엇을 하는지"만 알지 않는다.
 * "왜 존재하는지"를 안다.
 *
 * IntentNode:
 *   intent   — 이 노드가 달성하려는 의미 (자연어 + 구조화)
 *   contract:
 *     requires — 이 노드가 작동하려면 무엇이 참이어야 하나?
 *     ensures  — 이 노드가 성공하면 무엇이 참이 되나?
 *     produces — 이 노드가 그래프에 공급하는 Facts
 */

'use strict';

// ─── Fact 시스템 ───────────────────────────────────────────────
// Facts: 그래프에서 참/거짓을 판단할 수 있는 의미적 조건들
// 형식: "<도메인>.<속성>.<상태>"

const FACT_LIBRARY = {
  // 폼 도메인
  'form.email.filled':        '이메일 필드에 값이 입력됨',
  'form.password.filled':     '비밀번호 필드에 값이 입력됨',
  'form.name.filled':         '이름 필드에 값이 입력됨',
  'form.valid':               '폼 전체가 유효한 상태',
  'form.submitted':           '폼 제출 동작이 발생',

  // 인증 도메인
  'auth.initiated':           '인증 요청이 시작됨',
  'auth.succeeded':           '인증이 성공함',
  'auth.failed':              '인증이 실패함',
  'user.session.created':     '사용자 세션이 생성됨',

  // UI 상태 도메인
  'ui.button.clickable':      '버튼이 클릭 가능한 상태',
  'ui.button.connected':      '버튼에 핸들러가 연결됨',
  'ui.input.reactive':        '입력 필드가 상태와 연결됨',
  'ui.feedback.visible':      '사용자에게 피드백이 표시됨',
  'ui.rendered':              'UI가 화면에 렌더링됨',

  // 데이터 도메인
  'state.initialized':        '상태가 초기화됨',
  'state.bound':              '상태가 UI에 바인딩됨',
  'data.available':           '데이터가 사용 가능한 상태',

  // 내비게이션 도메인
  'nav.route.defined':        '라우트가 정의됨',
  'nav.transition.possible':  '화면 전환이 가능한 상태',

  // 결제 도메인
  'payment.info.collected':   '결제 정보가 수집됨',
  'payment.validated':        '결제 정보가 검증됨',
  'payment.initiated':        '결제가 시작됨',

  // 일반
  'action.handler.present':   '동작 핸들러가 존재함',
  'action.triggered':         '동작이 트리거됨',
  'output.displayed':         '출력이 화면에 표시됨',
};

// ─── 노드 타입별 기본 Intent + Contract ────────────────────────

const NODE_INTENT_DEFAULTS = {
  button: {
    intent: 'UI 인터랙션 제공 — 사용자가 동작을 실행할 수 있게 한다',
    contract: {
      requires: [],
      ensures:  ['ui.button.clickable', 'action.triggered'],
      produces: ['ui.button.clickable'],
      warns:    ['ui.button.connected'],  // 권장 (없어도 동작하지만 의미 없음)
    },
  },
  input: {
    intent: '사용자 입력 수집 — 데이터를 시스템에 주입한다',
    contract: {
      requires: [],
      ensures:  ['data.available'],
      produces: ['data.available'],
      warns:    ['ui.input.reactive'],
    },
  },
  text: {
    intent: '정보 표시 — 시스템 상태나 데이터를 사용자에게 보여준다',
    contract: {
      requires: [],
      ensures:  ['output.displayed'],
      produces: ['output.displayed'],
    },
  },
  card: {
    intent: '컨텐츠 그룹화 — 관련된 UI 요소들을 의미 단위로 묶는다',
    contract: {
      requires: [],
      ensures:  ['ui.rendered'],
      produces: ['ui.rendered'],
    },
  },
  container: {
    intent: '레이아웃 구조화 — UI 요소들의 공간 관계를 정의한다',
    contract: {
      requires: [],
      ensures:  ['ui.rendered'],
      produces: ['ui.rendered'],
    },
  },
  state: {
    intent: '상태 관리 — 시스템의 가변 데이터를 추적한다',
    contract: {
      requires: [],
      ensures:  ['state.initialized', 'data.available'],
      produces: ['state.initialized', 'data.available'],
    },
  },
  handler: {
    intent: '이벤트 처리 — 사용자 행위를 시스템 동작으로 변환한다',
    contract: {
      requires: ['ui.button.clickable'],
      ensures:  ['ui.button.connected', 'action.handler.present'],
      produces: ['action.handler.present', 'ui.button.connected'],
    },
  },
  setState: {
    intent: '상태 갱신 — 이벤트 발생 시 상태를 새 값으로 교체한다',
    contract: {
      requires: ['action.handler.present', 'state.initialized'],
      ensures:  ['state.bound'],
      produces: ['state.bound'],
    },
  },
  condition: {
    intent: '분기 제어 — 조건에 따라 다른 경로를 실행한다',
    contract: {
      requires: ['data.available'],
      ensures:  ['action.triggered'],
      produces: [],
    },
  },
};

// ─── 시나리오별 Intent Template ────────────────────────────────

const INTENT_SCENARIOS = {
  'login-form': {
    label: '로그인 폼',
    description: '이메일과 비밀번호로 사용자를 인증한다',
    goalFacts: ['auth.initiated', 'ui.button.connected', 'form.email.filled', 'form.password.filled'],
    nodeIntents: {
      email_input:    { intent: '이메일 수집', produces: ['form.email.filled', 'data.available'] },
      password_input: { intent: '비밀번호 수집', produces: ['form.password.filled', 'data.available'] },
      login_button:   { intent: '인증 시작', contract: { requires: ['form.email.filled','form.password.filled'], ensures: ['auth.initiated'] } },
      login_handler:  { intent: '로그인 요청 처리', produces: ['auth.initiated'] },
    },
  },
  'counter': {
    label: '카운터',
    description: '숫자를 증가/감소시켜 상태 변화를 표시한다',
    goalFacts: ['state.bound', 'ui.button.connected', 'output.displayed'],
    nodeIntents: {
      count_state:  { intent: '카운트 상태 보관', produces: ['state.initialized'] },
      display_text: { intent: '현재 카운트 표시', contract: { requires: ['state.initialized'], ensures: ['state.bound'] } },
      inc_button:   { intent: '카운트 증가', contract: { requires: [], ensures: ['action.triggered'] } },
      inc_handler:  { intent: '증가 동작 처리', produces: ['action.handler.present'] },
    },
  },
  'data-form': {
    label: '데이터 입력 폼',
    description: '사용자로부터 데이터를 수집하고 제출한다',
    goalFacts: ['form.submitted', 'ui.button.connected', 'data.available'],
    nodeIntents: {
      input_field:   { intent: '데이터 수집', produces: ['data.available'] },
      submit_button: { intent: '제출 실행', contract: { requires: ['data.available'], ensures: ['form.submitted'] } },
      submit_handler:{ intent: '제출 처리', produces: ['action.handler.present'] },
    },
  },
};

// ─── IntentNode 팩토리 ─────────────────────────────────────────

/**
 * 일반 노드에 Intent + Contract를 부여한다
 */
function withIntent(nodeDef, intentOverride = {}) {
  const defaults = NODE_INTENT_DEFAULTS[nodeDef.subtype] ?? {
    intent: `${nodeDef.subtype} 노드`,
    contract: { requires: [], ensures: [], produces: [] },
  };

  return {
    ...nodeDef,
    intent: intentOverride.intent ?? defaults.intent,
    contract: {
      requires: intentOverride.requires ?? defaults.contract.requires ?? [],
      ensures:  intentOverride.ensures  ?? defaults.contract.ensures  ?? [],
      produces: intentOverride.produces ?? defaults.contract.produces ?? [],
      warns:    intentOverride.warns    ?? defaults.contract.warns    ?? [],
    },
  };
}

/**
 * 시나리오 기반 Intent Graph 생성 도우미
 */
function createIntentGraph(scenarioKey, nodes) {
  const scenario = INTENT_SCENARIOS[scenarioKey];
  if (!scenario) return nodes;

  return nodes.map(node => {
    const ni = scenario.nodeIntents[node.id] ?? scenario.nodeIntents[node.subtype];
    if (!ni) return withIntent(node);
    return withIntent(node, ni);
  });
}

// ─── Intent 분석기 ─────────────────────────────────────────────

/**
 * 자연어 목표 → Goal Facts 변환
 * "로그인 폼" → ['auth.initiated', 'ui.button.connected', ...]
 */
function parseGoalToFacts(goalText) {
  const t = goalText.toLowerCase();
  const facts = new Set(['ui.rendered']);

  if (/로그인|login|sign.?in/.test(t)) {
    ['auth.initiated', 'ui.button.connected', 'form.email.filled', 'form.password.filled']
      .forEach(f => facts.add(f));
  }
  if (/회원가입|register|sign.?up/.test(t)) {
    ['form.submitted', 'ui.button.connected', 'data.available', 'form.name.filled']
      .forEach(f => facts.add(f));
  }
  if (/카운터|counter/.test(t)) {
    ['state.bound', 'ui.button.connected', 'output.displayed']
      .forEach(f => facts.add(f));
  }
  if (/검색|search/.test(t)) {
    ['data.available', 'ui.button.connected', 'output.displayed']
      .forEach(f => facts.add(f));
  }
  if (/결제|payment|checkout/.test(t)) {
    ['payment.initiated', 'payment.info.collected', 'ui.button.connected']
      .forEach(f => facts.add(f));
  }
  if (/버튼|button/.test(t)) {
    ['ui.button.clickable', 'action.triggered'].forEach(f => facts.add(f));
  }
  if (/폼|form/.test(t)) {
    ['form.submitted', 'data.available', 'ui.button.connected'].forEach(f => facts.add(f));
  }

  return [...facts];
}

module.exports = {
  withIntent,
  createIntentGraph,
  parseGoalToFacts,
  NODE_INTENT_DEFAULTS,
  INTENT_SCENARIOS,
  FACT_LIBRARY,
};

