     1→/**
     2→ * FreeWire Phase 10 — Adaptive Self-Correct Loop
     3→ *
     4→ * Phase 7의 SelfCorrectLoop + Phase 8의 RepairHistory + Phase 9의 ContractInferrer
     5→ * 모두가 하나로 합쳐진다.
     6→ *
     7→ * 이 루프는 단순히 수정하지 않는다.
     8→ *   1. 수정 전 — PatternAdvisor로 사전 경고 생성
     9→ *   2. 수정 중 — ContractInferrer로 누락 contract 자동 보완
    10→ *   3. 수정 후 — RepairHistory에 결과 기록
    11→ *   4. 다음 루프 — 기록된 효능으로 패치 신뢰도 보정
    12→ *
    13→ * 세션이 반복될수록 시스템이 나아진다.
    14→ * 이것이 "만족"이다.
    15→ */
    16→
    17→'use strict';
    18→
    19→const { IntentEvaluator }  = require('./evaluator');
    20→const { RepairEngine }     = require('./repair-engine');
    21→const { RepairHistory }    = require('./repair-history');
    22→const { PatternAdvisor }   = require('./pattern-advisor');
    23→const { ContractInferrer, mergeInferredContract } = require('./contract-inferrer');
    24→
    25→// ─── 전역 공유 이력 ─────────────────────────────────────────
    26→// 단일 인스턴스로 모든 세션 이력 축적
    27→const GLOBAL_HISTORY = new RepairHistory(1000);
    28→
    29→// ─── Adaptive Loop ──────────────────────────────────────────
    30→
    31→class AdaptiveLoop {
    32→  constructor({
    33→    maxIterations = 4,
    34→    targetScore   = 90,
    35→    history       = GLOBAL_HISTORY,
    36→    sessionId     = null,
    37→  } = {}) {
    38→    this.maxIterations = maxIterations;
    39→    this.targetScore   = targetScore;
    40→    this._history      = history;
    41→    this._sessionId    = sessionId ?? `s-${Date.now()}`;
    42→
    43→    this._evaluator = new IntentEvaluator();
    44→    this._repair    = new RepairEngine();
    45→    this._advisor   = new PatternAdvisor(history);
    46→    this._inferrer  = new ContractInferrer(history);
    47→  }
    48→
    49→  /**
    50→   * 단 하나의 공개 메서드.
    51→   *
    52→   * @param {string} goal
    53→   * @param {Map}    nodes   (mutable)
    54→   * @param {Map}    wires   (mutable)
    55→   * @param {Function} nextId
    56→   * @returns {AdaptiveLoopResult}
    57→   */
    58→  run(goal, nodes, wires, nextId = defaultNextId()) {
    59→    const trace         = [];
    60→    let   iteration     = 0;
    61→    let   lastReport    = null;
    62→    let   previousScore = 0;
    63→
    64→    // ── 사전 단계: Contract 자동 보완 ──────────────────────
    65→    const inferredContracts = this._inferrer.inferAll(nodes, wires, goal);
    66→    let inferCount = 0;
    67→    for (const [nodeId, inferred] of inferredContracts.entries()) {
    68→      const nodeView = nodes.get(nodeId);
    69→      if (nodeView) {
    70→        const def = nodeView.def ?? nodeView;
    71→        const merged = mergeInferredContract(def, inferred);
    72→        if (nodeView.def) nodeView.def = merged;
    73→        else nodes.set(nodeId, merged);
    74→        inferCount++;
    75→      }
    76→    }
    77→
    78→    // ── 사전 단계: 패턴 기반 사전 경고 ────────────────────
    79→    const nodesArr = [...nodes.values()].map(v => v.def ?? v);
    80→    const preAdvice = this._advisor.advise(nodesArr);
    81→
    82→    // ── 메인 루프 ─────────────────────────────────────────
    83→    while (iteration < this.maxIterations) {
    84→      iteration++;
    85→
    86→      // 1) 평가
    87→      const report = this._evaluator.evaluate(nodes, wires, goal);
    88→      lastReport   = report;
    89→
    90→      trace.push({
    91→        iteration,
    92→        score:      report.score,
    93→        errors:     report.errors.length,
    94→        warnings:   report.warnings.length,
    95→        patches:    [],
    96→        summary:    report.summary,
    97→        phase:      'evaluate',
    98→      });
    99→
   100→      if (report.passed && report.score >= this.targetScore) break;
   101→      if (report.errors.length === 0) break;
   102→
   103→      // 2) 패치 생성 + 이력 기반 신뢰도 보정
   104→      let patches = this._repair.suggest(report.violations, nodes, wires);
   105→      patches = this._advisor.adjustConfidence(patches);
   106→
   107→      if (patches.length === 0) break;
   108→
   109→      // 3) 패치 적용
   110→      const { applied, skipped } = this._repair.applyPatches(patches, nodes, wires, nextId);
   111→
   112→      // 4) 이력 기록
   113→      const newReport = this._evaluator.evaluate(nodes, wires, goal);
   114→      for (const patch of applied) {
   115→        const violation = report.violations.find(v =>
   116→          v.repairHint && patch.description.includes(
   117→            v.repairHint.replace(/_/g, ' ')
   118→          )
   119→        ) ?? report.violations[0];
   120→
   121→        if (violation) {
   122→          this._history.record(
   123→            this._sessionId,
   124→            { ...violation, nodeSubtype: violation.nodeId
   125→              ? ([...nodes.values()].map(v => v.def ?? v).find(n => n.id === violation.nodeId)?.subtype)
   126→              : null
   127→            },
   128→            patch,
   129→            newReport.score,
   130→            previousScore,
   131→          );
   132→        }
   133→      }
   134→
   135→      trace[trace.length - 1].patches = applied.map(p => ({
   136→        type:        p.type,
   137→        description: p.description,
   138→        confidence:  p.confidence,
   139→      }));
   140→      trace[trace.length - 1].skipped = skipped.length;
   141→
   142→      previousScore = report.score;
   143→
   144→      if (applied.length === 0) break;
   145→    }
   146→
   147→    // ── 사후 분석 ─────────────────────────────────────────
   148→    const sessionSummary = this._history.sessionSummary(this._sessionId);
   149→    const learningSummary = this._buildLearningSummary(
   150→      preAdvice, inferCount, sessionSummary
   151→    );
   152→
   153→    return {
   154→      goal,
   155→      sessionId:       this._sessionId,
   156→      iterations:      iteration,
   157→      converged:       lastReport?.passed ?? false,
   158→      finalScore:      lastReport?.score  ?? 0,
   159→      trace,
   160→      finalReport:     lastReport,
   161→      improved:        trace.length > 1
   162→        ? (trace[trace.length - 1].score > trace[0].score)
   163→        : false,
   164→      // Phase 8-10 전용
   165→      preAdvice,
   166→      inferredContracts: inferCount,
   167→      learningSummary,
   168→      historyStats:    this._history.stats(),
   169→    };
   170→  }
   171→
   172→  _buildLearningSummary(preAdvice, inferCount, sessionSummary) {
   173→    const parts = [];
   174→    if (inferCount > 0) {
   175→      parts.push(`Contract 자동 추론: ${inferCount}개 노드`);
   176→    }
   177→    if (preAdvice.length > 0) {
   178→      const high = preAdvice.filter(a => a.severity === 'high');
   179→      parts.push(`사전 경고: ${preAdvice.length}개${high.length > 0 ? ` (고위험 ${high.length}개)` : ''}`);
   180→    }
   181→    if (sessionSummary) {
   182→      parts.push(`이번 세션: ${sessionSummary.totalPatches}회 수정, 성공 ${sessionSummary.improved}회`);
   183→    }
   184→    const globalStats = this._history.stats();
   185→    if (globalStats.totalRecords > 0) {
   186→      parts.push(`누적 학습: ${globalStats.totalRecords}회 / 성공률 ${globalStats.successRate}%`);
   187→    }
   188→    return parts.join(' | ') || '학습 데이터 없음 (첫 세션)';
   189→  }
   190→
   191→  /**
   192→   * 이 루프가 축적한 전체 학습 리포트
   193→   */
   194→  learningReport() {
   195→    return this._advisor.learningReport();
   196→  }
   197→
   198→  /**
   199→   * 이력 직접 접근 (테스트/저장용)
   200→   */
   201→  get history() { return this._history; }
   202→}
   203→
   204→// ─── 전역 이력 공유 루프 (싱글턴 패턴) ─────────────────────
   205→
   206→/**
   207→ * 매 호출마다 같은 이력을 공유하는 루프 생성
   208→ * 세션을 넘어서도 이력이 누적된다
   209→ */
   210→function createAdaptiveLoop(options = {}) {
   211→  return new AdaptiveLoop({ history: GLOBAL_HISTORY, ...options });
   212→}
   213→
   214→/**
   215→ * 전역 이력 초기화 (테스트용)
   216→ */
   217→function resetGlobalHistory() {
   218→  GLOBAL_HISTORY._records       = [];
   219→  GLOBAL_HISTORY._patternIndex  = new Map();
   220→  GLOBAL_HISTORY._efficacyIndex = new Map();
   221→}
   222→
   223→/**
   224→ * 전역 이력에 접근
   225→ */
   226→function getGlobalHistory() {
   227→  return GLOBAL_HISTORY;
   228→}
   229→
   230→// ─── ID 생성기 팩토리 ───────────────────────────────────────
   231→
   232→function defaultNextId() {
   233→  let ctr = Date.now();
   234→  return () => `al-${ctr++}`;
   235→}
   236→
   237→module.exports = {
   238→  AdaptiveLoop,
   239→  createAdaptiveLoop,
   240→  resetGlobalHistory,
   241→  getGlobalHistory,
   242→  defaultNextId,
   243→  GLOBAL_HISTORY,
   244→};
   245→

