          nodeId: node.id, nodeLabel: node.label ?? node.subtype,
          type: 'structural', fact: 'node.connected',
          message: `노드 "${node.label ?? node.id}"가 다른 노드와 연결되지 않았습니다. 고립된 상태입니다.`,
          severity: 'warning',
          repairHint: 'connect_orphan',
        }));
      }
    }
  }

  // ─── 헬퍼 ────────────────────────────────────────────────────

  _extractDefs(nodes) {
    return [...nodes.values()].map(v => v.def ?? v);
  }

  _getDefaultContract(subtype) {
    return NODE_INTENT_DEFAULTS[subtype]?.contract ?? { requires: [], ensures: [], produces: [], warns: [] };
  }

  /**
   * 이 노드의 입력 포트에 연결된 노드들이 produces하는 facts
   */
  _factsProducedByInputs(node, nodesArr, wiresArr) {
    const produced = new Set();
    const inputWires = wiresArr.filter(w => (w.tn ?? w.to) === node.id);

    for (const wire of inputWires) {
      const sourceNode = nodesArr.find(n => n.id === (wire.fn ?? wire.from));
      if (!sourceNode) continue;
