    this.repairHint= repairHint; // 수정 방향 힌트
  }

  toString() {
    return `[${this.severity.toUpperCase()}] ${this.nodeLabel}: ${this.message}`;
  }
}

// ─── Intent Evaluator ──────────────────────────────────────────

class IntentEvaluator {
  /**
   * @param {Map}    nodes  - editor.nodes (NodeView Map)
   * @param {Map}    wires  - editor.wires (wire Map)
   * @param {string} goal   - 사용자 원래 의도 ("로그인 폼 만들어줘")
   */
  evaluate(nodes, wires, goal = '') {
    const nodesArr = this._extractDefs(nodes);
    const wiresArr = [...wires.values()];

    const violations = [];
    const satisfiedFacts = new Set();

    // 1) 구조 검사: 빈 그래프
    if (nodesArr.length === 0) {
      violations.push(new ContractViolation({
        nodeId: null, nodeLabel: '그래프',
        type: 'structural', fact: 'graph.nonempty',
        message: '노드가 없습니다. UI를 만들려면 노드를 추가하세요.',
        severity: 'error', repairHint: 'add_node',
      }));
      return this._buildReport(violations, satisfiedFacts, goal, nodesArr, wiresArr);
    }

    // 2) 각 노드의 Contract 검사
    for (const node of nodesArr) {
      const contract = node.contract ?? this._getDefaultContract(node.subtype);
      const producedByConnected = this._factsProducedByInputs(node, nodesArr, wiresArr);

      // requires 검사
      for (const req of (contract.requires ?? [])) {
        if (!producedByConnected.has(req) && !satisfiedFacts.has(req)) {
          violations.push(new ContractViolation({
            nodeId: node.id, nodeLabel: node.label ?? node.subtype,
            type: 'requires', fact: req,
            message: `"${req}" 조건이 필요하지만 연결된 노드가 제공하지 않습니다.`,
            severity: 'error',
            repairHint: `connect_${req.split('.')[0]}`,
          }));
        }
      }

      // warns 검사 (권장)
      for (const warn of (contract.warns ?? [])) {
        if (!producedByConnected.has(warn)) {
          violations.push(new ContractViolation({
            nodeId: node.id, nodeLabel: node.label ?? node.subtype,
            type: 'warning', fact: warn,
            message: `"${warn}" 조건이 충족되면 더 완전한 UI가 됩니다.`,
            severity: 'warning',
            repairHint: `enhance_${warn.split('.')[0]}`,
          }));
        }
      }

      // 이 노드가 produces하는 facts 수집
      for (const p of (contract.produces ?? [])) satisfiedFacts.add(p);
      for (const e of (contract.ensures ?? []))  satisfiedFacts.add(e);
    }

    // 3) 특수 구조 검사
    this._checkButtonHandlerConnections(nodesArr, wiresArr, violations);
    this._checkStateBindings(nodesArr, wiresArr, violations, satisfiedFacts);
    this._checkOrphanNodes(nodesArr, wiresArr, violations);

    // 4) Goal Facts 검사
    if (goal) {
      const goalFacts = parseGoalToFacts(goal);
      for (const gf of goalFacts) {
        if (!satisfiedFacts.has(gf)) {
          violations.push(new ContractViolation({
            nodeId: null, nodeLabel: '목표',
            type: 'goal', fact: gf,
            message: `목표 달성에 필요한 "${gf}"가 현재 그래프에서 생산되지 않습니다.`,
            severity: 'error',
            repairHint: `goal_${gf.replace(/\./g, '_')}`,
          }));
        }
      }
    }

    return this._buildReport(violations, satisfiedFacts, goal, nodesArr, wiresArr);
  }

  // ─── 특수 구조 검사들 ──────────────────────────────────────

  _checkButtonHandlerConnections(nodesArr, wiresArr, violations) {
    const buttons  = nodesArr.filter(n => n.subtype === 'button');
    const handlers = nodesArr.filter(n => n.subtype === 'handler');

    for (const btn of buttons) {
      // 버튼의 onClick 포트(인덱스 1)에 핸들러가 연결됐는지 확인
      const connected = wiresArr.some(w =>
        wireTo(w) === btn.id && (w.tp ?? w.toPort ?? w.to?.portId) === 1
      );
      if (!connected && handlers.length > 0) {
        violations.push(new ContractViolation({
          nodeId: btn.id, nodeLabel: btn.label ?? '버튼',
          type: 'structural', fact: 'ui.button.connected',
          message: `버튼 "${btn.props?.label ?? btn.id}"에 클릭 핸들러가 연결되지 않았습니다. 클릭해도 아무 일도 일어나지 않습니다.`,
          severity: 'error',
          repairHint: 'wire_handler_to_button',
        }));
      }
    }

    // 핸들러가 아예 없는데 버튼은 있는 경우
    if (buttons.length > 0 && handlers.length === 0) {
      violations.push(new ContractViolation({
        nodeId: null, nodeLabel: '그래프',
        type: 'structural', fact: 'action.handler.present',
        message: `버튼이 ${buttons.length}개 있지만 이벤트 핸들러가 없습니다. 버튼 클릭이 동작하지 않습니다.`,
        severity: 'error',
        repairHint: 'add_handler_node',
      }));
    }
  }

  _checkStateBindings(nodesArr, wiresArr, violations, satisfiedFacts) {
    const stateNodes = nodesArr.filter(n => n.subtype === 'state');
    const textNodes  = nodesArr.filter(n => n.subtype === 'text');

    for (const st of stateNodes) {
      // state가 text/컴포넌트에 연결됐는지
      const hasOutput = wiresArr.some(w => (w.fn ?? w.from) === st.id);
      if (!hasOutput && textNodes.length > 0) {
        violations.push(new ContractViolation({
          nodeId: st.id, nodeLabel: st.label ?? '상태',
          type: 'structural', fact: 'state.bound',
          message: `상태 "${st.props?.name ?? st.id}"가 UI에 바인딩되지 않았습니다. 상태가 변해도 화면이 갱신되지 않습니다.`,
          severity: 'warning',
          repairHint: 'wire_state_to_display',
        }));
      } else if (hasOutput) {
        satisfiedFacts.add('state.bound');
      }
    }
  }

  _checkOrphanNodes(nodesArr, wiresArr, violations) {
    if (nodesArr.length < 3) return; // 소규모 그래프는 고아 체크 생략

    for (const node of nodesArr) {
      if (node.type !== 'component') continue;
      const hasAnyWire = wiresArr.some(w =>
        (w.fn ?? w.from) === node.id || (w.tn ?? w.to) === node.id
      );
      if (!hasAnyWire) {
        violations.push(new ContractViolation({
          nodeId: node.id, nodeLabel: node.label ?? node.subtype,
          type: 'structural', fact: 'node.connected',
          message: `노드 "${node.label ?? node.id}"가 다른 노드와 연결되지 않았습니다. 고립된 상태입니다.`,
          severity: 'warning',
          repairHint: 'connect_orphan',
        }));
      }
    }
  }

  // ─── 헬퍼 ────────────────────────────────────────────────────

  _extractDefs(nodes) {
    return [...nodes.values()].map(v => v.def ?? v);
  }

  _getDefaultContract(subtype) {
    return NODE_INTENT_DEFAULTS[subtype]?.contract ?? { requires: [], ensures: [], produces: [], warns: [] };
  }

  /**
   * 이 노드의 입력 포트에 연결된 노드들이 produces하는 facts
   */
  _factsProducedByInputs(node, nodesArr, wiresArr) {
    const produced = new Set();
    const inputWires = wiresArr.filter(w => (w.tn ?? w.to) === node.id);

    for (const wire of inputWires) {
      const sourceNode = nodesArr.find(n => n.id === (wire.fn ?? wire.from));
      if (!sourceNode) continue;
      const contract = sourceNode.contract ?? this._getDefaultContract(sourceNode.subtype);
      for (const p of (contract.produces ?? [])) produced.add(p);
      for (const e of (contract.ensures  ?? [])) produced.add(e);
    }

    return produced;
  }

