    const errors   = violations.filter(v => v.severity === 'error');
    const warnings = violations.filter(v => v.severity === 'warning');

    const totalFacts     = parseGoalToFacts(goal || 'ui');
    const satisfiedGoals = totalFacts.filter(f => satisfiedFacts.has(f));
    const score = totalFacts.length > 0
      ? Math.round((satisfiedGoals.length / totalFacts.length) * 100)
      : (errors.length === 0 ? 100 : 0);

    return {
      score,                    // 0-100 — 의도 충족 점수
      passed: errors.length === 0,
      errors,
      warnings,
      violations,
      satisfiedFacts: [...satisfiedFacts],
      missingFacts: totalFacts.filter(f => !satisfiedFacts.has(f)),
