    };
  }

  _buildSummary(score, errors, warnings, nodesArr, wiresArr) {
    if (errors.length === 0 && warnings.length === 0) {
      return `✅ 의도 100% 충족 — 모든 계약이 만족됩니다`;
    }
    const parts = [];
    if (score < 100) parts.push(`의도 충족률: ${score}%`);
    if (errors.length)   parts.push(`오류 ${errors.length}개`);
    if (warnings.length) parts.push(`경고 ${warnings.length}개`);
    parts.push(`노드 ${nodesArr.length}개 / 와이어 ${wiresArr.length}개`);
    return parts.join(' | ');
  }
}

