/**
 * FreeWire Phase 10 — Adaptive Self-Correct Loop
 *
 * Phase 7의 SelfCorrectLoop + Phase 8의 RepairHistory + Phase 9의 ContractInferrer
 * 모두가 하나로 합쳐진다.
 *
 * 이 루프는 단순히 수정하지 않는다.
 *   1. 수정 전 — PatternAdvisor로 사전 경고 생성
 *   2. 수정 중 — ContractInferrer로 누락 contract 자동 보완
 *   3. 수정 후 — RepairHistory에 결과 기록
 *   4. 다음 루프 — 기록된 효능으로 패치 신뢰도 보정
 *
 * 세션이 반복될수록 시스템이 나아진다.
 * 이것이 "만족"이다.
 */

'use strict';

const { IntentEvaluator }  = require('./evaluator');
const { RepairEngine }     = require('./repair-engine');
const { RepairHistory }    = require('./repair-history');
const { PatternAdvisor }   = require('./pattern-advisor');
const { ContractInferrer, mergeInferredContract } = require('./contract-inferrer');

// ─── 전역 공유 이력 ─────────────────────────────────────────
// 단일 인스턴스로 모든 세션 이력 축적
const GLOBAL_HISTORY = new RepairHistory(1000);

// ─── Adaptive Loop ──────────────────────────────────────────

class AdaptiveLoop {
  constructor({
    maxIterations = 4,
    targetScore   = 90,
    history       = GLOBAL_HISTORY,
    sessionId     = null,
  } = {}) {
    this.maxIterations = maxIterations;
    this.targetScore   = targetScore;
    this._history      = history;
    this._sessionId    = sessionId ?? `s-${Date.now()}`;

    this._evaluator = new IntentEvaluator();
    this._repair    = new RepairEngine();
    this._advisor   = new PatternAdvisor(history);
    this._inferrer  = new ContractInferrer(history);
  }

  /**
   * 단 하나의 공개 메서드.
   *
   * @param {string} goal
   * @param {Map}    nodes   (mutable)
   * @param {Map}    wires   (mutable)
   * @param {Function} nextId
   * @returns {AdaptiveLoopResult}
   */
  run(goal, nodes, wires, nextId = defaultNextId()) {
    const trace         = [];
    let   iteration     = 0;
    let   lastReport    = null;
    let   previousScore = 0;

    // ── 사전 단계: Contract 자동 보완 ──────────────────────
    const inferredContracts = this._inferrer.inferAll(nodes, wires, goal);
    let inferCount = 0;
    for (const [nodeId, inferred] of inferredContracts.entries()) {
      const nodeView = nodes.get(nodeId);
      if (nodeView) {
        const def = nodeView.def ?? nodeView;
        const merged = mergeInferredContract(def, inferred);
        if (nodeView.def) nodeView.def = merged;
        else nodes.set(nodeId, merged);
        inferCount++;
      }
    }

    // ── 사전 단계: 패턴 기반 사전 경고 ────────────────────
    const nodesArr = [...nodes.values()].map(v => v.def ?? v);
    const preAdvice = this._advisor.advise(nodesArr);

    // ── 메인 루프 ─────────────────────────────────────────
    while (iteration < this.maxIterations) {
      iteration++;

      // 1) 평가
      const report = this._evaluator.evaluate(nodes, wires, goal);
      lastReport   = report;

      trace.push({
        iteration,
        score:      report.score,
        errors:     report.errors.length,
        warnings:   report.warnings.length,
        patches:    [],
        summary:    report.summary,
        phase:      'evaluate',
      });

      if (report.passed && report.score >= this.targetScore) break;
      if (report.errors.length === 0) break;

      // 2) 패치 생성 + 이력 기반 신뢰도 보정
      let patches = this._repair.suggest(report.violations, nodes, wires);
      patches = this._advisor.adjustConfidence(patches);

      if (patches.length === 0) break;

      // 3) 패치 적용
      const { applied, skipped } = this._repair.applyPatches(patches, nodes, wires, nextId);

      // 4) 이력 기록
      const newReport = this._evaluator.evaluate(nodes, wires, goal);
      for (const patch of applied) {
        const violation = report.violations.find(v =>
          v.repairHint && patch.description.includes(
            v.repairHint.replace(/_/g, ' ')
          )
        ) ?? report.violations[0];

        if (violation) {
          this._history.record(
            this._sessionId,
            { ...violation, nodeSubtype: violation.nodeId
              ? ([...nodes.values()].map(v => v.def ?? v).find(n => n.id === violation.nodeId)?.subtype)
              : null
            },
            patch,
            newReport.score,
            previousScore,
          );
        }
      }

      trace[trace.length - 1].patches = applied.map(p => ({
        type:        p.type,
        description: p.description,
        confidence:  p.confidence,
      }));
      trace[trace.length - 1].skipped = skipped.length;

      previousScore = report.score;

      if (applied.length === 0) break;
    }

    // ── 사후 분석 ─────────────────────────────────────────
    const sessionSummary = this._history.sessionSummary(this._sessionId);
    const learningSummary = this._buildLearningSummary(
      preAdvice, inferCount, sessionSummary
    );

    return {
      goal,
      sessionId:       this._sessionId,
      iterations:      iteration,
      converged:       lastReport?.passed ?? false,
      finalScore:      lastReport?.score  ?? 0,
      trace,
      finalReport:     lastReport,
      improved:        trace.length > 1
        ? (trace[trace.length - 1].score > trace[0].score)
        : false,
      // Phase 8-10 전용
      preAdvice,
      inferredContracts: inferCount,
      learningSummary,
      historyStats:    this._history.stats(),
    };
  }

  _buildLearningSummary(preAdvice, inferCount, sessionSummary) {
    const parts = [];
    if (inferCount > 0) {
      parts.push(`Contract 자동 추론: ${inferCount}개 노드`);
    }
    if (preAdvice.length > 0) {
      const high = preAdvice.filter(a => a.severity === 'high');
      parts.push(`사전 경고: ${preAdvice.length}개${high.length > 0 ? ` (고위험 ${high.length}개)` : ''}`);
    }
    if (sessionSummary) {
      parts.push(`이번 세션: ${sessionSummary.totalPatches}회 수정, 성공 ${sessionSummary.improved}회`);
    }
    const globalStats = this._history.stats();
    if (globalStats.totalRecords > 0) {
      parts.push(`누적 학습: ${globalStats.totalRecords}회 / 성공률 ${globalStats.successRate}%`);
    }
    return parts.join(' | ') || '학습 데이터 없음 (첫 세션)';
  }

  /**
   * 이 루프가 축적한 전체 학습 리포트
   */
  learningReport() {
    return this._advisor.learningReport();
  }

  /**
   * 이력 직접 접근 (테스트/저장용)
   */
  get history() { return this._history; }
}

// ─── 전역 이력 공유 루프 (싱글턴 패턴) ─────────────────────

/**
 * 매 호출마다 같은 이력을 공유하는 루프 생성
 * 세션을 넘어서도 이력이 누적된다
 */
function createAdaptiveLoop(options = {}) {
  return new AdaptiveLoop({ history: GLOBAL_HISTORY, ...options });
}

/**
 * 전역 이력 초기화 (테스트용)
 */
function resetGlobalHistory() {
  GLOBAL_HISTORY._records       = [];
  GLOBAL_HISTORY._patternIndex  = new Map();
  GLOBAL_HISTORY._efficacyIndex = new Map();
}

/**
 * 전역 이력에 접근
 */
function getGlobalHistory() {
  return GLOBAL_HISTORY;
}

// ─── ID 생성기 팩토리 ───────────────────────────────────────

function defaultNextId() {
  let ctr = Date.now();
  return () => `al-${ctr++}`;
}

module.exports = {
  AdaptiveLoop,
  createAdaptiveLoop,
  resetGlobalHistory,
  getGlobalHistory,
  defaultNextId,
  GLOBAL_HISTORY,
};

