/**
 * FreeWire Phase 7 — Self-Correct Loop
 *
 * 루프가 닫힌다.
 *
 * 생성 → 평가 → [score < 100?] → 수리 → 재평가 → ...
 *         ↑__________________________________|
 *
 * 이 루프가 돌 때 사람은 개입하지 않는다.
 * 시스템이 스스로 의도에 근접해간다.
 */

'use strict';

const { IntentEvaluator } = require('./evaluator');
const { RepairEngine }    = require('./repair-engine');

class SelfCorrectLoop {
  constructor({ maxIterations = 3, targetScore = 85 } = {}) {
    this.maxIterations = maxIterations;
    this.targetScore   = targetScore;
    this.evaluator     = new IntentEvaluator();
    this.repair        = new RepairEngine();
  }

  /**
   * 단 하나의 공개 메서드.
   * 목표 텍스트와 그래프를 받아서, 자기 수정 루프를 돌린다.
   *
   * @param {string} goal    - 사용자 원래 의도
   * @param {Map}    nodes   - 현재 노드 맵 (mutable)
   * @param {Map}    wires   - 현재 와이어 맵 (mutable)
   * @param {Function} nextId - ID 생성기
   * @returns {LoopResult}
   */
  run(goal, nodes, wires, nextId = defaultNextId()) {
    const trace = [];
    let iteration = 0;
    let lastReport = null;

    while (iteration < this.maxIterations) {
      iteration++;

      // 1) 평가
      const report = this.evaluator.evaluate(nodes, wires, goal);
      lastReport = report;

      trace.push({
        iteration,
        score:      report.score,
        errors:     report.errors.length,
        warnings:   report.warnings.length,
        patches:    [],
        summary:    report.summary,
      });

      // 목표 달성
      if (report.passed && report.score >= this.targetScore) {
        break;
      }

      // 오류 없음 (경고만)
      if (report.errors.length === 0) {
        break;
      }

      // 2) 수리 패치 생성
      const patches = this.repair.suggest(report.violations, nodes, wires);
      if (patches.length === 0) break; // 수리 방법 없음

      // 3) 패치 적용
      const { applied } = this.repair.applyPatches(patches, nodes, wires, nextId);
      trace[trace.length - 1].patches = applied.map(p => ({
        type: p.type, description: p.description, confidence: p.confidence,
      }));

      if (applied.length === 0) break; // 아무것도 적용 안 됨 (무한루프 방지)
    }

    return {
      goal,
      iterations:    iteration,
      converged:     lastReport?.passed ?? false,
      finalScore:    lastReport?.score  ?? 0,
      trace,
      finalReport:   lastReport,
      improved:      trace.length > 1
        ? (trace[trace.length - 1].score > trace[0].score)
        : false,
    };
  }
}

// ─── 단일 평가만 (루프 없이) ────────────────────────────────────

function evaluateOnce(goal, nodes, wires) {
  const evaluator = new IntentEvaluator();
  return evaluator.evaluate(nodes, wires, goal);
}

// ─── ID 생성기 팩토리 ───────────────────────────────────────────

function defaultNextId() {
  let ctr = Date.now();
  return () => `rc-${ctr++}`;
}

module.exports = { SelfCorrectLoop, evaluateOnce, defaultNextId };

