const { IntentEvaluator } = require('./src/intent/evaluator');
const { ContractInferrer } = require('./src/intent/contract-inferrer');
const { SelfCorrectLoop } = require('./src/intent/self-correct-loop');
const { AdaptiveLoop } = require('./src/intent/adaptive-loop');

// Graph 형식 엣지로 테스트
const nodes = new Map([
  ['btn1', { id: 'btn1', type: 'component', subtype: 'button', label: '버튼[+]',
    inputs: [], outputs: [], props: { label: '+' },
    contract: { requires: [], ensures: ['ui.button.clickable'], produces: ['ui.button.clickable'], warns: [] } }],
  ['st1', { id: 'st1', type: 'data', subtype: 'state', label: '상태[count]',
    inputs: [], outputs: [], props: { name: 'count', value: 0 },
    contract: { requires: [], ensures: ['state.initialized'], produces: ['state.initialized', 'data.available'], warns: [] } }],
  ['txt1', { id: 'txt1', type: 'component', subtype: 'text', label: '텍스트',
    inputs: [], outputs: [], props: {},
    contract: { requires: [], ensures: ['output.displayed'], produces: ['output.displayed'], warns: [] } }],
]);

// Graph 형식 엣지 (from.nodeId 구조)
const wires = new Map([
  ['w1', { id: 'w1', from: { nodeId: 'st1', portId: 'out', portType: 'data' }, to: { nodeId: 'txt1', portId: 'in', portType: 'data' } }],
]);

const ev = new IntentEvaluator();
const r = ev.evaluate(nodes, wires, '카운터');
console.log('score:', r.score, '| errors:', r.errors.length, '| warnings:', r.warnings.length);
console.log('passed:', r.passed);

// ContractInferrer 테스트
const ci = new ContractInferrer();
const btn = nodes.get('btn1');
const inferred = ci.infer(btn, [...nodes.values()], [...wires.values()], '카운터');
console.log('inferred counter.incremented:', inferred.produces.includes('counter.incremented'), '(+ label 테스트)');

// SelfCorrectLoop 스태그네이션 테스트
const loop = new SelfCorrectLoop({ maxIterations: 10 });
const result = loop.run('카운터', nodes, wires);
console.log('loop iterations:', result.iterations, '(max=10, should stop early)');
