     1→/**
     2→ * FreeWire - .free 코드 → HTML/CSS/JS 실행기
     3→ * FreeLang Light 컴파일러 로직을 내장하여 의존성 없이 동작
     4→ */
     5→
     6→class FreeExecutor {
     7→  /**
     8→   * @param {string} freeCode  - GraphCompiler가 생성한 .free 문자열
     9→   * @param {object} graphJson - 원본 그래프 JSON (메타 정보 참조용)
    10→   * @returns {{ html: string, css: string, js: string, stats: object }}
    11→   */
    12→  execute(freeCode, graphJson = {}) {
    13→    const sections = this._parseSections(freeCode);
    14→
    15→    const css  = this._compileStyle(sections.style);
    16→    const js   = this._compileScript(sections.script);
    17→    const html = this._compileMarkup(sections.markup);
    18→
    19→    return {
    20→      html,
    21→      css,
    22→      js,
    23→      stats: {
    24→        htmlBytes: html.length,
    25→        cssBytes:  css.length,
    26→        jsBytes:   js.length,
    27→        sections:  Object.keys(sections).filter(k => sections[k]),
    28→      },
    29→    };
    30→  }
    31→
    32→  // ─── 파서: .free 섹션 분리 ──────────────────────────────────
    33→
    34→  _parseSections(code) {
    35→    const sections = { props: '', style: '', script: '', markup: '' };
    36→    const pattern  = /\b(props|style|script|markup)\s*\{/g;
    37→    let match;
    38→    const positions = [];
    39→
    40→    while ((match = pattern.exec(code)) !== null) {
    41→      positions.push({ type: match[1], start: match.index + match[0].length });
    42→    }
    43→
    44→    positions.forEach((pos, i) => {
    45→      const end   = i + 1 < positions.length
    46→        ? this._findBlockEnd(code, pos.start - 1)
    47→        : this._findBlockEnd(code, pos.start - 1);
    48→      const inner = code.slice(pos.start, end).trim();
    49→      sections[pos.type] += '\n' + inner;
    50→    });
    51→
    52→    return sections;
    53→  }
    54→
    55→  _findBlockEnd(code, openBrace) {
    56→    // openBrace 위치에서 '{' 찾기
    57→    let idx = openBrace;
    58→    while (idx < code.length && code[idx] !== '{') idx++;
    59→    let depth = 1;
    60→    idx++;
    61→    while (idx < code.length && depth > 0) {
    62→      if (code[idx] === '{') depth++;
    63→      else if (code[idx] === '}') depth--;
    64→      idx++;
    65→    }
    66→    return idx - 1;
    67→  }
    68→
    69→  // ─── CSS 컴파일 ─────────────────────────────────────────────
    70→
    71→  _compileStyle(styleBlock) {
    72→    if (!styleBlock.trim()) return '';
    73→
    74→    // camelCase → kebab-case
    75→    return styleBlock
    76→      .replace(/([a-z])([A-Z])/g, '$1-$2')
    77→      .toLowerCase()
    78→      .replace(/\s*\n\s*/g, '\n')
    79→      .trim();
    80→  }
    81→
    82→  // ─── JS 컴파일 ──────────────────────────────────────────────
    83→
    84→  _compileScript(scriptBlock) {
    85→    if (!scriptBlock.trim()) return '';
    86→
    87→    const lines = scriptBlock.split('\n').map(l => l.trim()).filter(Boolean);
    88→    const output = [];
    89→
    90→    output.push('(function() {');
    91→    output.push('  "use strict";');
    92→
    93→    lines.forEach(line => {
    94→      // 주석 라인은 그대로
    95→      if (line.startsWith('//')) {
    96→        output.push('  ' + line);
    97→        return;
    98→      }
    99→      // 변수 선언
   100→      if (line.startsWith('let ') || line.startsWith('const ')) {
   101→        output.push('  ' + line);
   102→        return;
   103→      }
   104→      // 함수 선언
   105→      if (line.startsWith('function ')) {
   106→        output.push('  ' + line);
   107→        return;
   108→      }
   109→      // if/else
   110→      if (line.startsWith('if ') || line.startsWith('if(') ||
   111→          line.startsWith('} else') || line === '}' || line === '{') {
   112→        output.push('  ' + line);
   113→        return;
   114→      }
   115→      // 기타 (map/filter/reduce 결과 등)
   116→      output.push('  ' + line);
   117→    });
   118→
   119→    // DOM 준비 후 state 바인딩
   120→    output.push('  // DOM 이벤트 바인딩');
   121→    output.push('  document.addEventListener("DOMContentLoaded", function() {');
   122→    output.push('    var btns = document.querySelectorAll("button");');
   123→    output.push('    btns.forEach(function(btn) {');
   124→    output.push('      btn.addEventListener("click", function() {');
   125→    output.push('        if (typeof handleClick === "function") handleClick(this);');
   126→    output.push('        if (typeof increment  === "function") increment();');
   127→    output.push('        _updateDOM();');
   128→    output.push('      });');
   129→    output.push('    });');
   130→    output.push('    _updateDOM();');
   131→    output.push('  });');
   132→    output.push('  function _updateDOM() {');
   133→    output.push('    var displays = document.querySelectorAll("[data-bind]");');
   134→    output.push('    displays.forEach(function(el) {');
   135→    output.push('      var key = el.getAttribute("data-bind");');
   136→    output.push('      try { el.textContent = eval(key); } catch(e) {}');
   137→    output.push('    });');
   138→    output.push('  }');
   139→    output.push('})();');
   140→
   141→    return output.join('\n');
   142→  }
   143→
   144→  // ─── HTML 컴파일 ────────────────────────────────────────────
   145→
   146→  _compileMarkup(markupBlock) {
   147→    if (!markupBlock.trim()) return '';
   148→
   149→    let html = markupBlock
   150→      // 중첩 markup { } 제거
   151→      .replace(/markup\s*\{/g, '')
   152→      .replace(/^\s*\}\s*$/gm, '')
   153→      // {{변수}} → <span data-bind="변수">변수</span>
   154→      .replace(/\{\{(\w+)\}\}/g, '<span data-bind="$1">$1</span>')
   155→      // 빈 줄 정리
   156→      .replace(/\n{3,}/g, '\n\n')
   157→      .trim();
   158→
   159→    return html;
   160→  }
   161→}
   162→
   163→module.exports = { FreeExecutor };
   164→

