   101→class IntentParser {
   102→  parse(text) {
   103→    const t = text.toLowerCase().trim();
   104→
   105→    // 1) 직접 패턴
   106→    for (const [pattern, intent] of PATTERNS) {
   107→      if (pattern.test(t)) return { ...intent, raw: text };
   108→    }
   109→
   110→    // 2) 키워드 추출로 복합 의도
   111→    const keywords = this._extractKeywords(t);
   112→    return this._buildFromKeywords(keywords, text);
   113→  }
   114→
   115→  _extractKeywords(t) {
   116→    const kw = { components: [], data: [], logic: [], style: 'column', title: null };
   117→
   118→    // 제목
   119→    const titleMatch = t.match(/["']([^"']+)["']/) || t.match(/제목[은이]?\s*(.+?)(?:\s+|$)/);
   120→    if (titleMatch) kw.title = titleMatch[1];
   121→
   122→    // 컴포넌트
   123→    if (/(버튼|button|클릭|submit|제출|확인|취소|저장|삭제|추가)/.test(t)) kw.components.push('button');
   124→    if (/(텍스트|text|제목|title|label|표시|출력)/.test(t)) kw.components.push('text');
   125→    if (/(입력|input|필드|field|이메일|email|비밀번호|password|이름|name|검색|search)/.test(t)) kw.components.push('input');
   126→    if (/(카드|card)/.test(t)) kw.components.push('card');
   127→    if (/(리스트|list|목록|항목)/.test(t)) kw.components.push('list');
   128→
   129→    // 데이터
   130→    if (/(상태|state|카운트|count)/.test(t)) kw.data.push('state');
   131→    if (/(배열|array|list|목록|아이템)/.test(t)) kw.data.push('array');
   132→
   133→    // 로직
   134→    if (/(핸들러|클릭|이벤트|handler|event|onClick)/.test(t)) kw.logic.push('handler');
   135→    if (/(조건|if|else|분기)/.test(t)) kw.logic.push('condition');
   136→
   137→    // 레이아웃
   138→    if (/(가로|row|수평|horizontal)/.test(t)) kw.style = 'row';
   139→
   140→    return kw;
   141→  }
   142→
   143→  _buildFromKeywords(kw, raw) {
   144→    // 컴포넌트가 없으면 일반 텍스트로
   145→    if (kw.components.length === 0 && kw.data.length === 0) {
   146→      return { type: 'generic', label: raw, raw };
   147→    }
   148→    return { type: 'custom', keywords: kw, raw };
   149→  }
   150→}
